function toastUndo(msg,undo,ms=6000,label='되돌리기'){let old=document.querySelector('.toast');old?.remove();const el=document.createElement('div');el.className='toast toast-undo';el.innerHTML='<span></span><button type="button"></button>';el.querySelector('button').textContent=label;el.querySelector('span').textContent=msg;el.querySelector('button').onclick=()=>{el.remove();clearTimeout(toastTimer);try{undo()}catch(e){toast(e.message||String(e))}};document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),ms)}
function toast(msg,ms=3500){let old=document.querySelector('.toast');old?.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),ms||3500)}
