async function mountGymMap(){const el=document.getElementById('gym-map');if(!el||el===gymMapEl||!gymMap||gymMap.failed)return;gymMapEl=el;try{const kakao=await loadKakao();if(gymMapEl!==el||!el.isConnected||!gymMap)return;const c=gymMap.center;gymMapView=new kakao.maps.Map(el,{center:new kakao.maps.LatLng(c.lat,c.lng),level:c.level});const view=gymMapView;kakao.maps.event.addListener(view,'idle',()=>{if(view!==gymMapView||!gymMap)return;const p=view.getCenter();gymMap.center={lat:p.getLat(),lng:p.getLng(),level:view.getLevel()};clearTimeout(gymMapTimer);gymMapTimer=setTimeout(gymMapNearby,350)});gymMapNearby()}catch(e){if(!gymMap)return;gymMap={...gymMap,failed:true,status:'error',message:e.message};gymMapEl=null;render()}}
