async function publishMachineRequest(id){const r=catalogRequests.find(x=>x.id===id);if(!r||r.type!=='machine')return false;/* 4.7.0 헬스장 머신 한꺼번에 요청: 메모의 모델 id·헬스장 키로 바로 등록 */const gq=parseGymRequest(r.note);if(gq){if(gq.baseId&&!String(gq.modelId).match(/^(gm|bm):/)&&!(sharedCatalog.machineModels||[]).some(m=>m.id===gq.modelId))await saveSharedCatalogItem('machineModels',newModel(r.manufacturer,r.model,gq.baseId));await saveSharedCatalogItem('gymMachines',{id:gymMachineId(gq.gymKey,gq.modelId),name:`${r.gymName} · ${r.manufacturer==='일반 머신'?r.model:`${r.manufacturer} ${r.model}`}`.slice(0,160),gymName:r.gymName,gymKey:gq.gymKey,modelId:gq.modelId,...(gq.spec?{spec:gq.spec}:{})});return true}if(!r.manufacturer||!r.model)return false;const modelId=brandModelId(r.manufacturer,r.model),ex=findExerciseByName(r.name);await saveSharedCatalogItem('machineModels',{id:modelId,name:r.name||`${r.manufacturer} ${r.model}`,manufacturer:r.manufacturer,model:r.model,exerciseId:ex?.id||'',targetIds:r.targetIds||[]});if(r.gymName)await saveSharedCatalogItem('gymMachines',{id:gymMachineId(r.gymName,modelId),name:`${r.gymName} · ${r.manufacturer} ${r.model}`,gymName:r.gymName,modelId});return true}
async function shareReportCard(){const c=drawShareCard(buildReport(db,new Date(),{focus:analysisExercise}));const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('이미지를 만들지 못했어요.');const file=new File([blob],`mylogue-report-${today().slice(0,7)}.png`,{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'마이로그 이번 달 리포트'});return}catch(e){if(e.name==='AbortError')return}}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('리포트 카드 이미지를 저장했어요.')}
// 3.13.1 뒤로가기: 화면 이동·팝업 열기를 브라우저 기록에 남겨, 뒤로가기(웹·Android)로 팝업을 닫거나 이전 화면으로 간다.
const PAGES=['home','body','food','workout','analysis','calendar','settings','ai-inbox'];
function syncHistory(prevPage,prevModal){
 if(typeof history==='undefined'||typeof history.pushState!=='function')return;
 if(navFromPop){navFromPop=false;return}
 const st=history.state||{};
 if(prevModal&&!modal&&st.m){if(page!==prevPage)history.replaceState({p:page},'',`#${page}`);else{ignorePop=true;history.back()}return}
 if(prevPage!==null&&page!==prevPage){history.pushState({p:page},'',`#${page}`);setTimeout(()=>globalThis.scrollTo?.(0,0),0)}
 if(!prevModal&&modal)history.pushState({p:page,m:1},'');
}
if(typeof window!=='undefined'&&typeof window.addEventListener==='function'&&typeof history!=='undefined'&&history.replaceState){
 try{history.scrollRestoration='manual';history.replaceState({p:page},'',location.hash&&PAGES.includes(location.hash.slice(1))?location.hash:`#${page}`)}catch{}
 window.addEventListener('popstate',e=>{
  if(ignorePop){ignorePop=false;return}
  const st=e.state||{};
  if(modal){if(sheetDirty&&dirtyModal===modal&&!confirm('작성 중인 내용이 아직 저장되지 않았어요. 닫으면 지금 바꾼 내용이 사라져요. 닫을까요?')){history.pushState({p:page,m:1},'');return}
   sheetDirty=false;navFromPop=true;const x=document.getElementById('close');if(x)x.click();else{modal=null;render()}setTimeout(()=>{navFromPop=false},0);return}
  const next=PAGES.includes(st.p)?st.p:'home';
  if(next!==page){navFromPop=true;persistDraft();page=next;render();globalThis.scrollTo?.(0,0);setTimeout(()=>{navFromPop=false;globalThis.scrollTo?.(0,0)},0)}
 });
}
async function countPopularity(){if(cloudState.approval!=='approved')return;const key=scopedKey('mylogue.pop-counted');let done;try{done=new Set(JSON.parse(localStorage.getItem(key)||'[]'))}catch{done=new Set()}const since=new Date(Date.now()-30*86400000).toISOString().slice(0,10),entries=[],mark=[];
 for(const m of db.meals||[]){if(done.has(m.id)||m.date<since)continue;mark.push(m.id);entries.push({kind:'foods',id:popId(m.name),name:m.name})}
 for(const w of db.workouts||[]){if(done.has(w.id)||w.date<since)continue;mark.push(w.id);for(const e of w.exercises||[]){if(e.kind!=='cardio'&&!(e.sets||[]).some(x=>x.completed!==false))continue;entries.push({kind:'exercises',id:popId(e.exerciseId||e.name),name:e.name});if(/^(gm|mm):/.test(e.machineId||''))entries.push({kind:'machines',id:popId(e.machineId),name:e.machineId})}}
 if(!mark.length)return;try{if(entries.length)await bumpPopularity(entries)}catch(e){console.warn(e);return}const all=[...done,...mark].slice(-4000);try{localStorage.setItem(key,JSON.stringify(all))}catch{}}
async function refreshPopularity(){if(cloudState.approval!=='approved')return;try{popularity=await loadPopularity()}catch(e){console.warn('인기 집계를 불러오지 못했어요',e?.message)}}
function recordHint(){const pf=prefsOf(db);if(pf.hintShown||!pf.onboarded)return;if(db.body.length+db.meals.length+db.workouts.length<3)return;db=save(withPrefs(db,{hintShown:true}));setTimeout(()=>toast('기록 방식이 불편하면 설정 › 나의 기록 방식에서 바꿀 수 있어요.'),1800)}
function prefsClick(t){
 if(t.id==='onb-start'||t.id==='onb-restart'){onb=newOnboarding(db);modal='onboarding';render();return true}
 if(t.id==='onb-dismiss'){db=save(skipOnboarding(db));render();toast('설정 › 나의 기록 방식에서 언제든 맞출 수 있어요.');return true}
 if(t.dataset.onbPick&&onb){onboardingPick(onb,t.dataset.onbPick);render();return true}
 if(t.id==='onb-next'&&onb){onboardingMove(onb,1);render();return true}
 if(t.id==='onb-prev'&&onb){onboardingMove(onb,-1);render();return true}
 if(t.id==='onb-skip'&&onb){onb.step=QUESTIONS.length;render();return true}
 if(t.id==='onb-finish'&&onb){db=save(finishOnboarding(db,onb.answers));onb=null;modal=null;page='home';if(prefsOf(db).tracks.includes('meal')&&!db.settings.nutritionProfile){goalWiz=newGoalWizard(db);modal='goal-wizard';render();toast('이어서 식단 목표를 정해 볼게요. 건너뛰어도 돼요.');return true}render();toast('나에게 맞춘 설정으로 시작해요.');return true}
 if(t.dataset.pref){const was=prefsOf(db).glp1,r=applyPrefClick(db,t);if(r.db!==db)db=save(r.db);render();/* 4.7.0 GLP-1을 켜면 단백질 기준 목표를 다시 제안받게 */if(t.dataset.pref==='glp1'&&!was&&prefsOf(db).glp1&&Number(db.settings.calorieGoal)){toastUndo('단백질을 체중 기준으로 다시 맞출까요? 목표 문답을 열어요.',()=>{goalWiz=newGoalWizard(db);modal='goal-wizard';render()},10000,'다시 제안받기');return true}if(r.message)toast(r.message);return true}
 if(t.dataset.prefJump){page='settings';modal=null;scrollToPrefs=true;render();return true}
 if(t.id==='after-add'||t.id==='after-last'||t.dataset.afterDel!=null){const form=document.getElementById('after-workout-form');afterWorkout=form?readAfterWorkoutForm(form):(afterWorkout||emptyAfterWorkout(today()));if(t.id==='after-add')afterWorkout.rows.push({name:'',weight:'',reps:'',sets:3,unit:'kg'});if(t.id==='after-last'){if(!db.workouts.length){toast('불러올 지난 운동이 없어요.');return true}const last=afterWorkoutFromLast(db,afterWorkout.date,afterWorkout.gymName);afterWorkout={...afterWorkout,rows:last.rows}}if(t.dataset.afterDel!=null){afterWorkout.rows.splice(Number(t.dataset.afterDel),1);if(!afterWorkout.rows.length)afterWorkout.rows.push({name:'',weight:'',reps:'',sets:3,unit:'kg'})}render();return true}
 if(t.dataset.simpleSlot){const f=document.getElementById('simple-meal-form');if(f){f.querySelector('[name=slot]').value=t.dataset.simpleSlot;f.querySelectorAll('[data-simple-slot]').forEach(b=>{b.classList.toggle('on',b===t);b.setAttribute('aria-pressed',String(b===t))})}return true}
 if(t.dataset.simpleKcal){const f=document.getElementById('simple-meal-form');if(f)f.querySelector('[name=calories]').value=t.dataset.simpleKcal;return true}
 return false;
}
function accountChip(){const s=cloudState;if(!s.configured||(s.native&&!nativeAuthAvailable()))return '';if(!s.user)return `<button type="button" class="account-chip account-login" id="cloud-login" aria-label="Google 계정으로 로그인"><span class="account-avatar" aria-hidden="true"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 4.5-6 8-6s6.5 2 8 6"/></svg></span><span class="account-text"><strong>로그인</strong><small>기록 동기화</small></span></button>`;const pr=profileOf(db,s.user),status={pending:['승인 대기','wait'],not_applied:['신청 필요','wait'],rejected:['반려됨','bad']}[s.approval]||(s.approval==='approved'?null:['확인 중','wait']);return `<button type="button" class="account-chip" id="profile-open" aria-label="내 프로필: ${esc(pr.name)}${status?', '+status[0]:''}">${avatarHTML(pr)}<span class="account-text"><strong>${esc(pr.name)}</strong>${status?`<small class="account-status ${status[1]}">${status[0]}</small>`:''}</span></button>`}
const header=()=>`<header class="header${coach.headerClass()}"><div class="brand brand-home" data-page="home" role="link" tabindex="0" aria-label="마이로그 홈으로 · 오늘 ${haloProgress().done}/${haloProgress().total} 기록" title="오늘 ${haloProgress().done}/${haloProgress().total} 기록">${brandMarkHTML(haloProgress())}<div class="brand-words"><h1 class="brand-title">마이로그</h1><div class="brand-en">mylogue</div></div></div><div class="header-account">${noticeOn()?bellHTML(adminItems().length):''}${installChip()}${accountChip()}</div>${coach.headerExtra()}</header>`;
const nav=()=>{const ci=coach.navItems();if(ci)return `<nav class="nav coach-nav"><div class="nav-inner">${ci.map(([id,label,icon])=>`<button data-page="${id}" class="${page===id?'active':''}${id==='coach-schedule'?' nav-special nav-home':id==='coach-send'?' nav-special nav-add':''}"><b>${brandIcon(icon,'',page===id)}</b>${label}</button>`).join('')}</div></nav>`;const tr=prefsOf(db).tracks,need={body:'body',food:'meal',workout:'workout'};return `<nav class="nav"><div class="nav-inner">${[['body','수치'],['food','식단'],['workout','운동'],['home','홈'],['quick','추가'],['analysis','분석'],['calendar','일정'],['settings','설정']].filter(([id])=>!need[id]||tr.includes(need[id])).map(([id,label])=>id==='quick'?`<button data-modal="quick" class="nav-special nav-add" aria-label="빠른 기록"><b>${brandIcon('add','',true)}</b>${label}</button>`:`<button data-page="${id}" class="${page===id?'active':''}${id==='home'?' nav-special nav-home':''}"><b>${brandIcon(id,'',page===id)}</b>${label}</button>`).join('')}</div></nav>`};
function home(){const pf=prefsOf(db);return `${cloudState.user&&!pf.onboarded&&onbChecked&&modal!=='onboarding'?`<section class="section card onb-card"><h3>나에게 맞추기</h3><p class="hint">질문 몇 개로 기록 방식을 내게 맞게 정해요. 30초면 끝나요.</p><div class="actions"><button class="button" id="onb-start">맞추기 시작</button><button class="button secondary" id="onb-dismiss">괜찮아요</button></div></section>`:''}${renderHomeTimeline(db,selectedDate,{...homePlanOpts(selectedDate),dateBar:dateBar('home'),isToday:selectedDate===today(),motivHtml:todayLineHTML(new Date(),{open:motivOpen})})}<section class="section card ai-entry-card"><h3>AI가 작성한 기록</h3><p class="hint">사진이나 말로 부탁한 기록은 검토함에서 확인한 뒤 저장하세요.</p><button class="button secondary" data-page="ai-inbox">AI 검토함 열기</button></section>`}
function aiSettingsHTML(){
 const st=aiBridge.status,mine=st?.paired&&st.uid===cloudState.user?.uid,other=st?.paired&&!mine;
 const badge=mine?'<span class="status-badge ok">✓ 연결됨</span>':st?'<span class="status-badge wait">연결 전</span>':'<span class="status-badge info">도구 꺼짐</span>';
 let body;
 if(!cloudState.user)body='<p class="hint">로그인한 뒤 AI 도구를 연결할 수 있어요.</p>';
 else if(aiBridge.checking&&!aiBridge.checked)body='<p class="hint">이 PC의 AI 도구를 찾는 중…</p>';
 else if(mine)body=`<div class="ai-connected"><b>이 PC의 AI 도구와 연결돼 있어요</b><span>${st.persistent?'이 PC에서는 계속 연결돼요. 도구를 다시 켜도 자동으로 이어져요.':'연결이 곧 만료돼요. 다시 연결하면 계속 유지돼요.'}</span><small>AI가 쓴 초안은 ‘AI 검토함’에 쌓이고, 확인한 것만 내 기록이 돼요.</small></div><div class="actions"><button type="button" class="button secondary" data-page="ai-inbox">AI 검토함 열기</button><button type="button" class="text-button" id="ai-unpair">이 PC 연결 해제</button></div>`;
 else if(st)body=`<p>${other?'이 PC의 AI 도구가 다른 계정에 연결돼 있어요. 누르면 지금 계정으로 바꿔요.':'이 PC에서 AI 도구가 켜져 있어요. 버튼 한 번이면 연결돼요.'}</p><button type="button" class="button wide" id="ai-pair-now">이 PC의 AI 도구와 연결</button><p class="hint">한 번 연결하면 이 PC에서는 계속 유지돼요. 연결 정보는 이 PC의 사용자 폴더에만 저장되고, ‘연결 해제’로 지울 수 있어요.</p>`;
 else body=`<p>이 PC에서 AI 도구를 찾지 못했어요.</p><ol class="ai-steps"><li>Codex·Claude 같은 AI 앱에 마이로그 도구(agent-bridge)를 등록해 켜 두세요.</li><li>이 화면에서 ‘다시 찾기’를 누르면 연결 버튼이 나와요.</li></ol><div class="actions"><button type="button" class="button secondary" id="ai-bridge-check">${aiBridge.checking?'찾는 중…':'다시 찾기'}</button></div><p class="hint">휴대전화에서는 연결할 수 없어요. 연결은 AI 도구가 있는 PC의 브라우저에서 해 주세요. 연결한 뒤에는 휴대전화에서도 검토함과 알림을 볼 수 있어요.</p>`;
 return `<section class="section card ai-pair-card${mine?' connected':''}" id="ai-connect"><h3>내 AI 연결 ${badge}</h3>${body}<details class="ai-advanced"><summary>고급: 포트 바꾸기</summary><form id="ai-port-form" class="actions"><input name="port" type="number" min="1024" max="65535" inputmode="numeric" value="${esc(aiBridge.port)}" aria-label="AI 도구 포트"><button class="button secondary">이 포트로 찾기</button></form><p class="hint">기본 포트는 ${BRIDGE_PORT}이에요. 다른 프로그램이 쓰고 있으면 도구가 알려 주는 포트를 넣어 주세요.</p></details></section>`;
}
async function checkBridge(force=false){if(!cloudState.user||aiBridge.checking)return;if(!force&&aiBridge.checked&&Date.now()-(aiBridge.at||0)<15000)return;aiBridge.checking=true;if(page==='settings')render();aiBridge.status=await bridgeStatus(aiBridge.port);aiBridge.checking=false;aiBridge.checked=true;aiBridge.at=Date.now();if(aiBridge.status?.paired&&aiBridge.status.uid===cloudState.user.uid&&!prefsOf(db).aiLinked)db=save(withPrefs(db,{aiLinked:true}));if(page==='settings')render()}
async function aiBridgeClick(t){
 if(t.id==='ai-bridge-check'){await checkBridge(true);return true}
 if(t.id==='ai-pair-now'){t.disabled=true;const result=await pairLocalAgent(aiBridge.port);db=save(withPrefs(db,{aiLinked:true}));await checkBridge(true);toast(result.persistent?'AI 도구와 연결했어요. 이 PC에서는 계속 연결돼요.':'AI 도구와 연결했어요.');refreshAIDrafts().catch(console.error);return true}
 if(t.id==='ai-unpair'){if(!confirm('이 PC의 AI 도구 연결을 해제할까요? 이 PC에 저장된 연결 정보가 지워져요.'))return true;await unpairLocalAgent(aiBridge.port);try{localStorage.removeItem(scopedKey('mylogue.ai-pair'))}catch{}aiPair=null;await checkBridge(true);toast('이 PC의 AI 연결을 해제했어요.');return true}
 return false;
}
function bodyPage(){if(!['overview','weight','inbody','waistCm'].includes(bodyMetric))bodyMetric=bodyMetric==='bodyFatPct'||bodyMetric==='skeletalMuscle'?'inbody':'overview';const label={overview:'한눈에',weight:'체중',inbody:'인바디',waistCm:'허리둘레'},td=today(),sc=scaleRecords(db),ib=inbodyRecords(db),last=sc.at(-1),lastIb=ib.at(-1),lastWaist=recent(db.body).find(x=>x.waistCm!=null);
 const periods=`<div class="seg period-seg" role="group" aria-label="그래프 기간">${[[7,'7일'],[30,'30일'],[90,'90일'],[3650,'전체']].map(([v,l])=>`<button type="button" class="${period===v?'active':''}" data-period="${v}" aria-pressed="${period===v}">${l}</button>`).join('')}</div>`;
 let head='',graph='';
 if(bodyMetric==='overview'){return `<div class="page-head"><div><span class="eyebrow">Body</span><h2>내 수치</h2><p>몸의 흐름을 한눈에 봐요.</p></div><button class="button" data-modal="body">＋ 기록</button></div><div class="tabs">${Object.entries(label).map(([k,v])=>`<button data-metric="${k}" class="${bodyMetric===k?'active':''}">${v}</button>`).join('')}</div>${bodyOverviewHTML(db,{view:bfView,today:td})}`}
 if(bodyMetric==='weight'){head=`<span class="sub">평소 체중계 · ${last?esc(last.date):'기록 없음'}</span><h3 class="body-big">${last?fmt(last.weight,1):'—'} <span class="unit">kg</span></h3>`;graph=bodyChartHTML([{name:'체중',cls:'s-weight',unit:'kg',pts:sc.map(x=>({date:x.date,v:x.weight}))},{name:'7일 평균',cls:'s-trend',unit:'kg',dashed:true,pts:smoothWeights(sc)}],{days:period,today:td,empty:'평소 체중계로 잰 체중을 기록하면 여기에 이어져요.'})+'<p class="hint">인바디로 잰 체중은 기계가 달라 이 그래프에 섞지 않고 ‘인바디’에서 따로 봐요. 점선은 최근 7일 평균이에요.</p>'}
 else if(bodyMetric==='inbody'){head=`<span class="sub">인바디 · ${lastIb?esc(lastIb.date):'기록 없음'}</span><h3 class="body-big">${lastIb?`${fmt(lastIb.weight,1)} <span class="unit">kg</span>`:'—'}</h3>${lastIb?`<p class="body-sub">골격근 ${fmt(lastIb.skeletalMuscle,1)}kg · 체지방 ${fmt(lastIb.bodyFatMass,1)}kg · ${fmt(lastIb.bodyFatPct,1)}%</p>`:''}`;graph=`<div class="seg unit-seg" role="group" aria-label="인바디 단위">${[['kg','kg 보기'],['pct','체지방률 %']].map(([v,l])=>`<button type="button" class="${inbodyUnit===v?'active':''}" data-inbody-unit="${v}" aria-pressed="${inbodyUnit===v}">${l}</button>`).join('')}</div>`+(inbodyUnit==='pct'?bodyChartHTML([{name:'체지방률',cls:'s-fatpct',unit:'%',pts:ib.map(x=>({date:x.date,v:x.bodyFatPct}))}],{days:period,today:td,empty:'인바디 결과를 넣으면 체지방률이 여기에 이어져요.'}):(ib.length?[['체중','s-weight','weight'],['골격근량','s-muscle','skeletalMuscle'],['체지방량','s-fat','bodyFatMass']].map(([n,c,k])=>`<div class="ib-row"><h4>${n}</h4>${bodyChartHTML([{name:n,cls:c,unit:'kg',pts:ib.map(x=>({date:x.date,v:x[k]}))}],{days:period,today:td,compact:true,empty:`이 기간에 ${n} 기록이 없어요.`})}</div>`).join(''):'<div class="empty">인바디 결과를 넣으면 체중·골격근량·체지방량이 따로 이어져요.</div>'))}
 else{head=`<span class="sub">허리둘레 · ${lastWaist?esc(lastWaist.date):'기록 없음'}</span><h3 class="body-big">${lastWaist?fmt(lastWaist.waistCm,1):'—'} <span class="unit">cm</span></h3>`;graph=bodyChartHTML([{name:'허리둘레',cls:'s-waist',unit:'cm',pts:(db.body||[]).filter(x=>x.waistCm!=null).map(x=>({date:x.date,v:x.waistCm}))}],{days:period,today:td})}
 return `<div class="page-head"><div><span class="eyebrow">Body</span><h2>내 수치</h2><p>체중·인바디·허리둘레를 자세히 봐요.</p></div><button class="button" data-modal="body">＋ 기록</button></div><div class="tabs">${Object.entries(label).map(([k,v])=>`<button data-metric="${k}" class="${bodyMetric===k?'active':''}">${v}</button>`).join('')}</div><div class="card body-card"><div class="body-card-head"><div>${head}</div>${periods}</div>${graph}</div><section class="section"><h3 class="section-title">인바디 결과지 <small>사진 또는 파일로 가져오기</small></h3><div class="actions"><button class="button secondary" data-modal="inbody">▧ 사진에서 읽기</button><button class="button secondary" data-modal="body-import">⇧ 숫자 파일 가져오기</button></div></section><section class="section"><h3 class="section-title">측정 기록</h3><div class="card">${db.body.length?recent(db.body).map(x=>`<div class="record"><div><strong>${esc(x.date)} · ${fmt(x.weight)} kg</strong><small>체지방 ${fmt(x.bodyFatPct)}% · 골격근 ${fmt(x.skeletalMuscle)} kg${x.source==='import'?' · 가져옴':''}${isInbody(x)?' · <b class="ib-tag">인바디</b>':''}</small></div><div class="record-actions"><button data-body-edit="${esc(x.id)}">수정</button><button data-delete="body:${esc(x.id)}">삭제</button></div></div>`).join(''):emptyArt('body','첫 측정 기록을 남겨보세요.')}</div></section><section class="section progress-section"><h3 class="section-title">눈바디 사진 <button class="text-button" data-modal="progress-photo">＋ 사진</button></h3><div class="progress-grid">${progressPhotos.length?progressPhotos.slice(-2).map(x=>`<div class="card"><img src="${x.url}" alt="${x.date} 눈바디 사진" class="progress-photo"><div class="record"><strong>${x.date}</strong><button data-progress-delete="${x.id}">삭제</button></div></div>`).join(''):'<div class="card empty">사진을 기기에 보관하면 최근 두 장을 나란히 비교합니다.</div>'}</div><p class="hint">사진은 기기에 보관되며 통합 백업에 포함됩니다. 백업 파일도 개인 정보이므로 안전하게 보관하세요.</p><div class="card" style="margin-top:10px">${progressPhotos.length?progressPhotos.map(x=>`<div class="record"><strong>${x.date}</strong><div class="record-actions"><button data-progress-export="${x.id}">사진 저장</button><button data-progress-delete="${x.id}">삭제</button></div></div>`).join(''):'<div class="empty">보관된 사진이 없습니다.</div>'}</div></section>`}
