  if(t.dataset.qFood){const item=quickFoodCandidates(foodChoices()).find(x=>`${x.name.toLocaleLowerCase('ko')}|${x.servingUnit||'g'}`===t.dataset.qFood);if(!item)throw Error('음식을 찾지 못했습니다.');if(['calories','carbs','protein','fat'].some(k=>item[k]==null))throw Error('영양값이 일부 없는 음식입니다. 상세 입력에서 라벨 값을 확인해 주세요.');s.picked=structuredClone(item);s.editIndex=-1;s.usual=usualQty(db.meals,item.name,item.servingUnit);s.qty=s.usual[0]?.qty??(MASS.has(item.servingUnit)?(db.settings.lastGrams?.[item.name]||100):1);s.gramOptions=db.settings.gramOptions?.[item.name]||[100,200,210,250,300];render();return true}
  if(t.dataset.qRecipe){const recipe=(db.recipes||[]).find(x=>x.id===t.dataset.qRecipe);if(!recipe)return true;for(const meal of recipeMeals(recipe,s.date,'식사',1)){const q=MASS.has(meal.servingUnit)?(db.settings.lastGrams?.[meal.name]||meal.servingQty):meal.servingQty,base=MASS.has(meal.servingUnit)?meal.servingQty/100:meal.servingQty;s.rows.push(quickFoodRow({...meal,...Object.fromEntries(['calories','carbs','protein','fat'].map(k=>[k,meal[k]==null?null:meal[k]/base]))},q))}render();return true}
  if(t.dataset.qGram){s.qty=Number(t.dataset.qGram);render();return true}
  if(t.dataset.qEditFood!==undefined){s.editIndex=Number(t.dataset.qEditFood);s.picked=structuredClone(s.rows[s.editIndex]);s.qty=s.picked.servingQty;s.gramOptions=db.settings.gramOptions?.[s.picked.name]||[100,200,210,250,300];render();return true}
  if(t.dataset.qRemoveFood!==undefined){s.rows.splice(Number(t.dataset.qRemoveFood),1);render();return true}
  if(t.id==='q-close-picker'){s.picked=null;render();return true}
