  if(form.id==='gym-map-form'){const name=String(d.name||'').trim();if(!name)throw Error('헬스장 이름을 입력해 주세요.');const c=gymMap?.center||{};let address='';try{address=await addressAt(c.lat,c.lng)}catch{}db=save(addGymPlace(db,{name,address,lat:c.lat,lng:c.lng,provider:'manual'}));closeGymMap();render();toast(`내 운동 장소에 ‘${name}’ 추가했어요.`);return}
  if(form.id==='after-workout-form'){afterWorkout=readAfterWorkoutForm(form);const w=planWorkout(afterWorkout&&afterWorkoutRecord(afterWorkout));db=save({...db,workouts:[...db.workouts,w]});afterWorkout=null;modal=null;page='workout';render();recordHint();toast(`${w.exercises.length}종목을 저장했습니다.`);return}
  if(form.id==='guide-plan-form'){guidePlan=readPlanForm(form);const items=validatePlan(guidePlan);const pf=prefsOf(db);guideRun=startRun(guidePlan,items);guideCues=createCues(pf.cue);guideCues.unlock();guideCues.keepAwake(pf.keepAwake);prepareNativeAlerts();guideStartTicker();modal='guide-run';render();guideCues.play({say:`${items[0].name}, 1세트 시작`,beep:1,go:1});return}
  if(form.id==='simple-meal-form'){const m=planMeal(simpleMealRecord(form));db=save({...db,meals:[...db.meals,m]});modal=null;render();recordHint();toast(m.planned?`${m.slot}을 예정으로 넣었어요.`:savedLine(db));return}
  if(form.id==='ai-port-form'){aiBridge.port=Number(d.port)||BRIDGE_PORT;await checkBridge(true);return}
  if(form.matches?.('[data-ai-draft]')){const draft=aiDrafts.find(x=>x.id===form.dataset.aiDraft);if(!draft)throw Error('AI 초안을 다시 불러와 주세요.');const reviewedData=readAIReview(form,draft);try{await resolveAIDraft(draft,{action:'confirm',reviewedData,existing:localRecords()})}catch(e){if(e?.code==='duplicate'&&confirm(`${e.message}

같은 걸 한 번 더 먹은 거라면 ‘확인’을 눌러 따로 저장해요.`))await resolveAIDraft(draft,{action:'confirm',reviewedData,allowDuplicate:true});else throw e}try{const synced=await synchronize(db,saveLocal);if(synced.db)db=synced.db}catch(error){toast(`기록은 서버에 저장됐습니다. 이 기기 동기화는 다시 시도해 주세요: ${error.message}`)}await refreshAIDrafts();toast('검토한 기록을 확정했습니다.');return}
