  if(form.id==='machine-form'){const aliases=String(d.aliases||'').split(',').map(x=>x.trim()).filter(Boolean);const item=cleanMachine({...d,id:d.recordId,photoDataUrl:machinePhoto,aliases});db=save({...db,machines:[...(db.machines||[]).filter(x=>x.id!==item.id),item]});if(machineIndex!==null&&workDraft[machineIndex]){workDraft[machineIndex].machineId=item.id;for(const set of workDraft[machineIndex].sets)if(Number(set.weight)===0)set.unit=item.unit}if(profileReturn==='quick-workout'&&quickWorkout){quickWorkout.machineId=item.id;quickWorkout.unit=item.unit}modal=profileReturn;render();toast('머신을 저장했습니다.');return}
