let tesseractPromise;async function getTesseract(){if(window.Tesseract)return window.Tesseract;if(!tesseractPromise)tesseractPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/tesseract.min.js';s.onload=()=>resolve(window.Tesseract);s.onerror=()=>reject(Error('OCR 도구를 불러오지 못했습니다. 인터넷 연결을 확인하거나 숫자 파일을 사용해 주세요.'));document.head.append(s)});return tesseractPromise}
async function runOCR(){const status=document.getElementById('ocr-status'),file=document.getElementById('inbody-photo').files?.[0]||(sharedPhoto?await (await fetch(sharedPhoto)).blob():null);if(!file)throw Error('사진을 선택해 주세요.');status.textContent='인바디 270 결과지의 숫자를 읽고 있습니다…';try{const T=await getTesseract();const result=await recognizeInBody270(file,T);document.getElementById('ocr-text').value=Object.entries(result.raw).map(([k,v])=>`${k}: ${v.trim()}`).join('\n');ocrFields(result.fields);status.textContent='숫자 읽기를 마쳤습니다. 모든 값을 원본과 비교한 뒤 저장해 주세요.'}catch(err){status.textContent=err.message;toast(err.message)}}async function shareWorkout(w){if(!w)return;const t=workoutTotals(w),canvas=document.createElement('canvas');canvas.width=900;canvas.height=920+Math.min(w.exercises.length,8)*54;const c=canvas.getContext('2d');c.fillStyle='#07111e';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#9ddcff';c.font='bold 26px sans-serif';c.fillText('MYLOGUE · 마이로그',48,60);c.fillStyle='#eaf4ff';c.font='bold 43px sans-serif';c.fillText(w.title,48,125);c.fillStyle='#a9bdd3';c.font='25px sans-serif';c.fillText(w.date,48,165);c.fillStyle='#3b8dff';c.font='bold 31px sans-serif';c.fillText(`${t.exercises}종목   ${t.sets}세트   ${t.reps}회   ${fmt(t.volume,0)} kg`,48,236);let y=300;for(const e of w.exercises.slice(0,8)){c.fillStyle='#eaf4ff';c.font='24px sans-serif';c.fillText(e.name,48,y);c.fillStyle='#a9bdd3';c.font='20px sans-serif';c.fillText(`${e.kind==='cardio'?`${fmt(e.durationMin)}분`:`완료 ${e.sets.filter(s=>s.completed!==false).length}세트`} · ${e.part}`,650,y);y+=54}const completedExercises=w.exercises.filter(e=>e.kind==='cardio'?(e.durationMin>0||e.distanceKm>0):e.sets.some(s=>s.completed!==false)),primary=[...new Set(completedExercises.flatMap(e=>e.primaryMuscleIds||[]))],secondary=[...new Set(completedExercises.flatMap(e=>e.secondaryMuscleIds||[]))].filter(x=>!primary.includes(x));for(const [i,side] of ['front','back'].entries()){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(anatomySvg(primary,secondary,{side,key:'export'}));await img.decode();c.drawImage(img,260+i*200,y+30,180,385)}c.fillStyle='#9ddcff';c.font='22px sans-serif';c.fillText('테크니컬 아틀라스 · 주 타깃 빨강 / 보조 사선',48,y+455);canvas.toBlob(blob=>{if(!blob){toast('이미지 생성에 실패했습니다.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mylogue-${w.date}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('운동 결과 이미지를 저장했습니다.')},'image/png')}
