function profilesHTML(){return `<details class="section card"><summary>내 머신·사용자 종목 관리</summary><h3>머신</h3>${(db.machines||[]).map(x=>`<div class="record"><strong>${esc(x.name)} · ${esc(x.manufacturer)} ${esc(x.model)}</strong><button data-edit-machine="${esc(x.id)}">수정</button></div>`).join('')||'<p class="hint">운동 입력 중 머신을 등록하세요.</p>'}<h3>나만의 종목</h3>${(db.customExercises||[]).map(x=>`<div class="record"><strong>${esc(x.name)}</strong><button data-edit-custom="${esc(x.id)}">수정</button></div>`).join('')||'<p class="hint">운동 도감에서 직접 등록할 수 있습니다.</p>'}</details>`}

function estimateFor(ex){return latestEstimate(db.workouts.map(w=>({...w,exercises:w.exercises.filter(e=>(ex.exerciseId?e.exerciseId===ex.exerciseId:e.name===ex.name)&&(e.machineId||null)===(ex.machineId||null))})),ex.name)}
async function readMachinePhoto(input){const file=input.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>10*1024*1024)throw Error('10 MB 이하 JPG·PNG·WebP 사진을 선택하세요.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();machinePhoto=canvas.toDataURL('image/jpeg',.8);const img=document.getElementById('machine-preview');img.src=machinePhoto;img.hidden=false}

function reviewHTML(){const c=comparePeriods(actualDB(db),30),w=weeklyReport(actualDB(db)),bodyDays=new Set(db.body.filter(x=>x.date>=w.from&&x.date<=w.to).map(x=>x.date)).size;return `<section class="section card"><h3>이번 주 기록과 이전 기간 비교</h3><p>수치 ${bodyDays}/7일 · 식단 완료/단식 ${w.completeDietDays}/7일 · 운동 ${w.workoutDays}/7일</p><p class="hint">식단 일부 ${w.partialDietDays}일 · 미기록 ${w.missingDietDays}일. 운동 없는 날은 자동으로 휴식으로 판단하지 않습니다.</p><p>직전 30일 대비 운동 ${c.workoutSessionsChange>0?'+':''}${c.workoutSessionsChange}회 · 기록 볼륨 ${fmt(c.volumeChange)} kg</p><p class="hint">식단 평균 차이 ${fmt(c.averageCaloriesChange)} kcal · 두 기간 모두 완료/단식일 기준이며 결측에 따라 비교 의미가 달라집니다. ${esc(c.note)}</p></section>`}

function loadAtlasHTML(key){const r=recommendWorkout(db,today());return `${muscleMapHTML([],[],{key,mode:'load',loads:r.loads})}<div class="atlas-load-list">${r.loads.map(x=>`<div class="record"><strong>${esc(MUSCLE_LABELS[x.muscleId]||x.muscleId)} · ${esc(x.level)}</strong><small>지표 ${fmt(x.score)} · 가중 세트 ${fmt(x.sets)}<br>마지막 기록 ${esc(x.lastDate)}</small></div>`).join('')||'<p class="hint">최근 완료 세트가 없어 부위별 부하를 판단하지 않습니다.</p>'}</div><details><summary>계산 근거와 미확인 정보</summary><p class="hint">${esc(r.note)}</p><p class="hint">미확인: ${esc(r.missing.join(', ')||'없음')}</p></details>`}

async function cloudClick(target){
 if(!target.id?.startsWith('cloud-'))return false;
 const id=target.id;
 if(id==='cloud-retry'){location.reload();return true}
 if(id==='cloud-login'){persistDraft();await cloudLogin();return true}
 if(id==='cloud-logout'){persistDraft();await cloudLogout();return true}
 if(id==='cloud-apply'){await applyForAccess(document.getElementById('approval-consent')?.checked===true);render();toast('기록 이용 신청을 보냈습니다. 승인 전에는 서버 기록을 사용할 수 없습니다.');return true}
 if(id==='cloud-approval-refresh'){await refreshApproval();render();if(cloudState.approval==='approved'){await refreshCatalog();queueAutoSync()}return true}
 if(id==='cloud-applicants-refresh'){await refreshApplicants();return true}
 if(id.startsWith('cloud-review-')){
  const match=/^cloud-review-(approved|pending|rejected)-([A-Za-z0-9]+)$/.exec(id);
  if(!match)throw Error('신청 항목을 확인해 주세요.');
  if(match[1]==='rejected'&&!confirm('이 계정의 서버 기록 접근을 중단하고 신청을 반려할까요? 기기 안의 기록은 삭제되지 않습니다.'))return true;
  await reviewApplicant(match[2],match[1]);adminJust={uid:match[2],status:match[1]};render();const who=cloudState.applicants.find(a=>a.uid===match[2])?.email||'이 계정';toast(match[1]==='approved'?`${who} 승인 완료 · 이제 기록 동기화를 쓸 수 있어요.`:match[1]==='rejected'?`${who} 반려 완료`:`${who} 승인 대기로 되돌렸어요.`);return true;
 }
 if(id==='cloud-conflicts-export'){download('mylogue-sync-conflicts.json',JSON.stringify(cloudState.conflicts,null,2));return true}
 if(id==='cloud-archive-export'){const raw=localStorage.getItem(scopedKey('mylogue.cloud.before-sync'));if(!raw)throw Error('보관된 동기화 원본이 없습니다.');download('mylogue-before-sync.json',raw);return true}
 if(id==='cloud-import-guest'){
  if(!cloudState.user||cloudState.approval!=='approved')throw Error('계정 이용 승인 후 사용할 수 있습니다.');
  if(['body','meals','foods','workouts','routines','machines','customExercises','recipes','favorites'].some(k=>db[k]?.length)||Object.keys(db.checkins||{}).length||Object.keys(db.dayStates||{}).length)throw Error('계정 기록이 비어 있을 때만 게스트 기록을 복사할 수 있습니다. 기존 기록은 백업으로 보관해 주세요.');
  const raw=localStorage.getItem('mylogue.v1');if(!raw)throw Error('이 브라우저에 게스트 기록이 없습니다.');
  if(!confirm('게스트의 숫자·텍스트 기록을 현재 계정 공간에 복사할까요? 사진과 초안은 제외합니다. 아직 서버에는 전송하지 않습니다.'))return true;
  db=save(recordsToDB(cloudRecords(normalizeDB(JSON.parse(raw)))));render();toast('계정 공간에 복사했습니다. 서버 전송은 지금 동기화를 눌러 주세요.');return true;
 }
 if(id==='cloud-sync'||id==='cloud-resolve'){
  const choices={};
  if(id==='cloud-resolve')for(const [i,c] of cloudState.conflicts.entries()){const side=document.querySelector(`[data-cloud-conflict="${i}"]`)?.value;if(!side)throw Error('모든 충돌 기록에서 유지할 내용을 선택해 주세요.');choices[c.key]={side,local:c.local,remote:c.remote};}
  if(!confirm(`${cloudState.user?.email||'현재 계정'}의 Firebase 저장소에 수치·식단·운동·설정 기록을 전송하고 서버 변경과 삭제를 반영할까요? 사진·초안은 전송하지 않습니다.`))return true;
  backupBusy=true;
  try{const result=await synchronize(db,saveLocal,choices);if(result.db)db=result.db;render();toast(result.conflicts.length?'충돌 내용을 확인해 주세요.':'기록 동기화를 완료했습니다.');}finally{backupBusy=false}
  return true;
 }
 return false;
}
async function catalogClick(target){
 if(target.dataset.adminFood){catalogAdminFood=catalogFoods().find(x=>x.id===target.dataset.adminFood)||null;render();return true}
 if(target.id==='admin-food-new'){catalogAdminFood=null;render();return true}
 if(target.dataset.requestPhoto){catalogPhotoView=await catalogRequestPhoto(target.dataset.requestPhoto);modal='catalog-photo';render();return true}
 if(target.dataset.reviewRequest){if(!isCatalogAdmin(cloudState.user))throw Error('관리자 계정만 요청을 검토할 수 있습니다.');const id=target.dataset.reviewRequest,status=document.querySelector(`[data-review-state="${CSS.escape(id)}"]`)?.value,note=document.querySelector(`[data-review-note="${CSS.escape(id)}"]`)?.value||'';await reviewCatalogRequest(id,{status,note});let published=false;if(status==='approved')try{published=await publishMachineRequest(id)}catch(e){toast(`승인했지만 공용 머신 등록은 실패했어요: ${e.message}`)}await refreshCatalog();if(published)toast('승인 완료 · 그 헬스장 머신 목록에 바로 나와요.');toast(status==='approved'?'승인 완료 · 요청 목록에 ‘승인됨’으로 표시돼요.':status==='rejected'?'반려 완료':'요청 상태를 바꿨어요.');return true}
 return false;
}


// 3.16.0 공유받은 AI 답: PWA 공유 대상(?text=)·Android 앱(네이티브가 남긴 값)
try{const q=new URLSearchParams(location.search),shared=[q.get('title'),q.get('text'),q.get('url')].filter(Boolean).join('\n');if(shared){history.replaceState(history.state,'',location.pathname+location.hash);setTimeout(()=>openAIInput(shared),400)}const pending=localStorage.getItem('mylogue.pendingShare');if(pending){localStorage.removeItem('mylogue.pendingShare');setTimeout(()=>openAIInput(pending),400)}const rec=q.get('record')||localStorage.getItem('mylogue.pendingShortcut');if(rec){if(q.get('record'))history.replaceState(history.state,'',location.pathname+location.hash);setTimeout(()=>openShortcut(rec),500)}if(globalThis.__mylogueSharedImage)setTimeout(()=>openSharedPhoto(globalThis.__mylogueSharedImage),500)}catch(error){console.error(error)}
// 3.19.0 체중 대비 탄단지 목표는 최근 체중으로 다시 계산
try{refreshGoalsByWeight()}catch(error){console.error(error)}

// 4.0.0 코치 모드: 초대 링크(?invite=)와 연동 불러오기(마스터 계정만, 다른 계정은 아무 일도 없음)
try{const q=new URLSearchParams(location.search),inv=q.get('invite');if(inv&&coach.takeInvite(inv)){history.replaceState(history.state,'',location.pathname+location.hash);page='settings';render();setTimeout(()=>document.getElementById('my-coach')?.scrollIntoView?.({block:'start'}),200)}}catch(error){console.error(error)}
try{if(coach.visible())coach.refresh().catch(console.error)}catch(error){console.error(error)}

// 4.2.0 날짜 바를 좌우로 밀면 하루 전·다음 날
{let sx=null,sy=null;root.addEventListener?.('touchstart',e=>{const b=e.target.closest?.('[data-datebar]');if(!b){sx=null;return}const t=e.touches[0];sx=t.clientX;sy=t.clientY},{passive:true});root.addEventListener?.('touchend',e=>{if(sx==null)return;const t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;sx=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.5){selectedDate=shiftDate(selectedDate,dx<0?1:-1);dbOpen=false;render()}},{passive:true})}
